def getjson(url,params=None):
    if params: url=url+'?'+urllib.parse.urlencode(params)
    elif '?' not in url: url=url+'?f=pjson'
    req=urllib.request.Request(url,headers=headers)
    with urllib.request.urlopen(req,timeout=30,context=ctx) as r: return json.loads(r.read().decode('utf-8'))
